package io.github.jesterportfolio.hearth.persistence;

import java.util.*;import java.util.concurrent.*;import java.sql.*;import javax.sql.DataSource;
import io.github.jesterportfolio.hearth.economy.*;import io.github.jesterportfolio.hearth.inventory.*;

public final class PlatformDatabaseChecks {
    static <T>T await(CompletionStage<T> s)throws Exception{return s.toCompletableFuture().get(12,TimeUnit.SECONDS);}
    static void check(boolean b,String name){if(!b)throw new IllegalStateException(name);System.out.println("HEARTH_PLATFORM_DB_CHECK PASS "+name);System.out.flush();}
    static void reject(CompletionStage<?> s)throws Exception{try{await(s);throw new IllegalStateException("EXPECTED_REJECTION");}catch(ExecutionException expected){}}
    public static void run(DataSource source,Connection c)throws Exception{
        var props=new Properties();try(var in=PlatformDatabaseChecks.class.getResourceAsStream("/economy-demo.properties")){props.load(in);}props.setProperty("fixture-balance","0");var db=PostgresProgressStore.forModules(source,f->{});var economy=new EconomyStore(db,EconomyContent.parse(props));await(economy.migrate());await(economy.migrate());UUID realm=UUID.randomUUID();await(economy.openNativeRealm(realm,UUID.randomUUID(),"a".repeat(64),1,true));var actor=economy.context(realm,UUID.randomUUID());var other=economy.context(realm,UUID.randomUUID());var empty=InventoryPayload.pack(new byte[41][]);await(economy.ensureAccount(actor,empty));await(economy.ensureAccount(other,empty));var p=new PlatformStore(db,economy,realm);await(p.requireInactive());check(true,"E012_migration_idempotent_and_empty_runtime_may_remain_disabled");
        var pref=new PlatformStore.Preference(true,Set.of("iron_ore"),-1);var a=p.preference(actor,pref,-1);var b=p.preference(actor,new PlatformStore.Preference(false,Set.of(),-1),-1);int wins=0;for(var op:List.of(a,b))try{await(op);wins++;}catch(ExecutionException expected){}check(wins==1&&await(p.preferences()).size()==1,"preference_first_write_CAS_has_one_winner");var saved=await(p.preferences()).get(actor.playerId());reject(p.preference(new ServerProgressAccess().forVerifiedServerLink(realm,actor.playerId()),pref,saved.revision()));check(true,"foreign_preference_context_is_denied");
        try(var s=c.prepareStatement("UPDATE hearth_economy.account SET balance=100 WHERE realm_id=? AND player_uuid=?")){s.setObject(1,realm);s.setObject(2,actor.playerId());s.executeUpdate();}var slots=new byte[41][];slots[0]=new byte[]{1,2};var after=InventoryPayload.pack(slots);var enchants=new EnchantStore(db,economy);UUID request=UUID.randomUUID();var intent=new EnchantStore.Intent(request,"fixed-upgrade-roll","UPGRADE","hearth:equipment_upgrade",empty,after,"SUCCESS",.5,.1,10,0);var left=enchants.execute(actor,intent,()->true);var right=enchants.execute(actor,intent,()->true);var l=await(left);var r=await(right);check(l.replay()!=r.replay()&&await(economy.account(actor)).balance()==90&&await(economy.account(actor)).inventory().revision()==1,"concurrent_upgrade_has_one_charge_and_shadow_commit");check((l.replay()?l:r).after()==null,"upgrade_replay_does_not_supply_inventory_for_regrant");
        var revoked=new EnchantStore.Intent(UUID.randomUUID(),"revoked","UPGRADE","hearth:equipment_upgrade",after,empty,"DOWN",0,.9,5,1);reject(enchants.execute(actor,revoked,()->false));check(await(economy.account(actor)).balance()==90,"revoked_upgrade_preserves_balance_and_equipment");
        UUID old=UUID.randomUUID(),reset=UUID.randomUUID();var first=await(p.reserve(reset,"novice",old,0,42,"FLAT"));check(await(p.reserve(reset,"novice",old,0,42,"FLAT")).equals(first),"same_reset_request_is_idempotent_before_world_creation");reject(p.reserve(UUID.randomUUID(),"novice",old,0,42,"FLAT"));reject(p.reserve(UUID.randomUUID(),"residence",old,0,42,"FLAT"));check(true,"concurrent_reset_and_residential_reset_are_denied");
        UUID world=UUID.randomUUID();var ready=await(p.prepared(first,world,.5,64,.5));await(p.activate(ready));reject(p.activate(ready));reject(p.requireInactive());check(await(p.resets()).getFirst().phase().equals("ACTIVE"),"generation_activates_once_and_disabled_runtime_cannot_bypass_it");reject(p.reserve(UUID.randomUUID(),"novice",old,1,43,"FLAT"));var pending=await(p.reserve(UUID.randomUUID(),"novice",world,1,43,"FLAT"));await(p.abort(pending.request()));var retry=await(p.reserve(UUID.randomUUID(),"novice",world,1,44,"FLAT"));check(retry.generation()==2,"aborted_generation_can_be_retried_without_deleting_old_rows");await(p.abort(retry.request()));
        UUID config=UUID.randomUUID();await(p.config(config,"platform.properties","a".repeat(64),"b".repeat(64),null,"PREPARED"));await(p.config(config,"platform.properties","a".repeat(64),"b".repeat(64),null,"PREPARED"));reject(p.config(config,"changed","a".repeat(64),"b".repeat(64),null,"PREPARED"));await(p.config(config,"platform.properties","a".repeat(64),"b".repeat(64),"PREPARED","COMMITTED"));reject(p.config(config,"platform.properties","a".repeat(64),"b".repeat(64),"PREPARED","COMMITTED"));check(await(p.configState(config)).equals("COMMITTED"),"configuration_request_identity_and_state_CAS_are_preserved");
        var next=(Properties)props.clone();next.setProperty("good.iron_ore.base","120");var content=EconomyPolicyMigration.validate(props,next);UUID migration=UUID.randomUUID();String beforeHash=economy.content().fingerprint(),afterHash=content.fingerprint();var account=await(economy.account(actor));EconomyPolicyMigration.swap(c,realm,migration,"economy",beforeHash,afterHash,false);EconomyPolicyMigration.swap(c,realm,migration,"economy",beforeHash,afterHash,false);var nextStore=new EconomyStore(db,content);await(nextStore.migrate());check(await(nextStore.account(nextStore.context(realm,actor.playerId()))).equals(account),"offline_economic_policy_migration_is_idempotent_and_preserves_wallet_inventory");EconomyPolicyMigration.swap(c,realm,migration,"economy",beforeHash,afterHash,true);check(await(economy.account(actor)).equals(account),"policy_rollback_keeps_latest_economic_data_instead_of_restoring_old_balances");
        try(var s=c.createStatement()){s.execute("CREATE FUNCTION hearth_economy.reject_platform_fixture() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'fixture failure' USING ERRCODE='23514'; END $$");s.execute("CREATE TRIGGER reject_platform_fixture BEFORE UPDATE ON hearth_economy.resource_reset FOR EACH ROW EXECUTE FUNCTION hearth_economy.reject_platform_fixture()");}var fail=await(p.reserve(UUID.randomUUID(),"end",UUID.randomUUID(),0,50,"NORMAL"));reject(p.prepared(fail,UUID.randomUUID(),0,64,0));check(await(p.resets()).stream().anyMatch(row->row.request().equals(fail.request())&&row.phase().equals("PREPARING")),"SQL_failure_keeps_original_reset_state_for_explicit_recovery");try(var s=c.createStatement()){s.execute("DROP TRIGGER reject_platform_fixture ON hearth_economy.resource_reset");s.execute("DROP FUNCTION hearth_economy.reject_platform_fixture()");}await(p.abort(fail.request()));
        check(await(p.configHistory()).size()==2,"read_only_configuration_history_is_realm_scoped");await(db.closeAsync());
    }
}
